-- events: created by `forge generate scaffold` for PostgreSQL.
-- Identifiers are UUIDv7 values generated by the application; the
-- database never generates them. `version` is the optimistic lock.
-- Rows belong to a tenant: the application binds `tenant_id` from the
-- authorized TenantContext, and row-level security (forced, so it also
-- applies to the table owner) is defense in depth.

CREATE TABLE "events" (
    "id" uuid NOT NULL PRIMARY KEY,
    "tenant_id" uuid NOT NULL,
    "name" text NOT NULL CONSTRAINT "events_name_length" CHECK (char_length("name") <= 255),
    "notes" text,
    "starts_at" timestamptz NOT NULL,
    "ends_at" timestamptz,
    "capacity" bigint NOT NULL,
    "attendees" bigint,
    "public" boolean NOT NULL,
    "featured" boolean,
    "venue" uuid NOT NULL,
    "organizer" uuid,
    "version" bigint NOT NULL DEFAULT 1 CONSTRAINT "events_version_positive" CHECK ("version" >= 1),
    "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX "events_tenant_id_idx" ON "events" ("tenant_id", "id");

ALTER TABLE "events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "events" FORCE ROW LEVEL SECURITY;

-- Without `forge.tenant_id` (set per transaction by
-- begin_tenant_transaction) no row is visible or writable.
CREATE POLICY "events_tenant_isolation" ON "events"
    FOR ALL
    USING ("tenant_id" = NULLIF(current_setting('forge.tenant_id', true), '')::uuid)
    WITH CHECK ("tenant_id" = NULLIF(current_setting('forge.tenant_id', true), '')::uuid);

REVOKE ALL ON TABLE "events" FROM PUBLIC;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_runtime') THEN
        GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE "events" TO app_runtime;
    END IF;
END
$$;
